"""Minimal pytest TAP reporter (stdlib only): one test point per test item, written to $GSD_TAP_OUT at session end.

A test is "not ok" when any phase (setup, call, teardown) failed, so a call failure plus a teardown error counts as
one failing test (pytest's JUnit writer emits two <testcase> elements for that case).
"""

import os

_order: list[str] = []
_names: dict[str, str] = {}
_status: dict[str, str] = {}


def pytest_runtest_logreport(report):
    nodeid = report.nodeid
    if nodeid not in _status:
        _order.append(nodeid)
        _names[nodeid] = nodeid.rsplit("::", 1)[-1]
        _status[nodeid] = "ok"
    if report.failed:
        _status[nodeid] = "fail"
    elif report.skipped and report.when == "setup" and _status[nodeid] == "ok":
        _status[nodeid] = "skip"


def pytest_sessionfinish(session, exitstatus):
    path = os.environ.get("GSD_TAP_OUT")
    if not path:
        return
    lines = ["TAP version 13", f"1..{len(_order)}"]
    for number, nodeid in enumerate(_order, 1):
        status = _status[nodeid]
        prefix = "not ok" if status == "fail" else "ok"
        suffix = " # SKIP" if status == "skip" else ""
        lines.append(f"{prefix} {number} - {_names[nodeid]}{suffix}")
    with open(path, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")
